fs = 1000;
t = (0:1/fs:5-1/fs)';
x = sin(2*pi*100*t) + 0.5*randn(size(t));
[pxx, f] = pwelch(x, hann(1024), 512, 2048, fs);
plot(f, 10*log10(pxx)); xlabel('Hz'); ylabel('dB/Hz')

fs = 1024;
t = (0:1/fs:1-1/fs)';
x = cos(2*pi*200*t);
[pxx, f] = periodogram(x, hamming(length(x)), 4096, fs, 'power');
plot(f, 10*log10(pxx)); grid on

fs = 500;
x = randn(512,1) + sin(2*pi*60*(0:511)'/fs);
[pxx, pxxc, f] = pmtm(x, 3.5, 1024, fs, 'ConfidenceLevel', 0.95);
plot(f, 10*log10([pxx pxxc]))

fs = 200;
x = filter(1, [1 -1.5 0.9], randn(1000,1));
[pxx, f] = pyulear(x, 4, 512, fs);
plot(f, 10*log10(pxx)); grid on

fs = 1000;
x = randn(10000,1);
y = filter(fir1(30, 0.2), 1, x);
[pxy, f] = cpsd(x, y, hann(512), 256, 1024, fs);
plot(f, angle(pxy)); ylabel('Phase (rad)')

fs = 1000;
x = randn(20000,1);
[b,a] = butter(4, 150/(fs/2));
y = filter(b, a, x);
[txy, f] = tfestimate(x, y, hann(1024), 512, 1024, fs);
semilogy(f, abs(txy))

fs = 4000;
t = (0:1/fs:3-1/fs)';
x = chirp(t, 100, 3, 1500) + 0.1*randn(size(t));
spectrogram(x, hann(256), 200, 512, fs, 'yaxis')
colorbar

fs = 8000;
t = (0:1/fs:1-1/fs)';
x = chirp(t, 200, 1, 2000);
win = hann(256, 'periodic');
[s, f, tt] = stft(x, fs, 'Window', win, 'OverlapLength', 192, 'FFTLength', 512);
imagesc(tt, f, 20*log10(abs(s))); axis xy

fs = 8000; win = hann(256,'periodic');
x = chirp((0:1/fs:1-1/fs)', 200, 1, 2000);
s = stft(x, fs, 'Window', win, 'OverlapLength', 192, 'FFTLength', 256);
xr = istft(s, fs, 'Window', win, 'OverlapLength', 192, 'FFTLength', 256, 'ConjugateSymmetric', true);
max(abs(x - xr(1:numel(x))))

fs = 3000;
t = (0:1/fs:2-1/fs)';
