y = hilbert(x);
env = abs(y);
instf = fs/(2*pi) * diff(unwrap(angle(y)));
plot(t, x, t, env)

fs = 2000;
t = (0:1/fs:1-1/fs)';
x = exp(-3*t) .* sin(2*pi*200*t);
[up, lo] = envelope(x, 60, 'peak');
plot(t, x, t, up, t, lo)

fs = 1000;
